class Solution:
    def stringHash(self, s: str, k: int) -> str:
        n = len(s)
        k = k

        # Check if length is divisible by k
        if n % k != 0:
            raise ValueError("s length must be divisible by k")

        result = []
        for i in range(0, n, k):
            substring = s[i:i+k]
            char_sum = sum(ord(c) - ord('a') for c in substring)
            hashed_char = char_sum % 26
            result.append(chr(hashed_char + ord('a')))
        return ''.join(result)
